/**
 * Lenis Smooth Scroll Engine (Lightweight, robust standalone build)
 * Replicates inertial momentum scrolling for LaunchNow Kora Framer templates
 */
(function(global) {
  'use strict';

  function clamp(val, min, max) {
    return Math.min(Math.max(val, min), max);
  }

  function damp(current, target, smooth, dt) {
    return current + (target - current) * (1 - Math.exp(-smooth * dt));
  }

  class Lenis {
    constructor(options = {}) {
      this.wrapper = options.wrapper || window;
      this.content = options.content || document.documentElement;
      this.smoothWheel = options.smoothWheel !== false;
      this.smoothTouch = options.smoothTouch === true;
      this.lerp = options.lerp || 0.1;
      this.duration = options.duration || 1.1;
      this.wheelMultiplier = options.wheelMultiplier || 1.0;
      this.touchMultiplier = options.touchMultiplier || 1.5;

      this.targetScroll = window.scrollY || window.pageYOffset;
      this.currentScroll = this.targetScroll;
      this.maxScroll = this.getMaxScroll();
      this.isStopped = false;
      this.isScrolling = false;
      this.rafId = null;
      this.time = performance.now();

      this.onScroll = options.onScroll || null;
      this._init();
    }

    getMaxScroll() {
      const body = document.body;
      const doc = document.documentElement;
      return Math.max(0, Math.max(
        body ? body.scrollHeight : 0,
        doc ? doc.scrollHeight : 0,
        body ? body.offsetHeight : 0,
        doc ? doc.offsetHeight : 0,
        body ? body.clientHeight : 0,
        doc ? doc.clientHeight : 0
      ) - (window.innerHeight || 0));
    }

    _init() {
      this._bindEvents();
      this._startRaf();
      document.documentElement.classList.add('lenis');
      document.documentElement.classList.add('lenis-smooth');
    }

    _bindEvents() {
      this._onWheel = this._onWheel.bind(this);
      this._onTouchStart = this._onTouchStart.bind(this);
      this._onTouchMove = this._onTouchMove.bind(this);
      this._onResize = this._onResize.bind(this);
      this._onKey = this._onKey.bind(this);

      window.addEventListener('wheel', this._onWheel, { passive: false });
      window.addEventListener('resize', this._onResize);
      window.addEventListener('keydown', this._onKey);

      if (this.smoothTouch) {
        window.addEventListener('touchstart', this._onTouchStart, { passive: true });
        window.addEventListener('touchmove', this._onTouchMove, { passive: false });
      }

      // Smooth scroll on anchor link clicks
      document.addEventListener('click', (e) => {
        const link = e.target.closest('a[href^="#"]');
        if (!link) return;
        const targetId = link.getAttribute('href');
        if (targetId === '#' || targetId === '') return;
        const targetEl = document.querySelector(targetId);
        if (targetEl) {
          e.preventDefault();
          this.scrollTo(targetEl, { offset: -80 });
        }
      });
    }

    _onWheel(e) {
      if (!this.smoothWheel || this.isStopped) return;
      if (e.ctrlKey) return; // Allow pinch-zoom

      e.preventDefault();
      this.maxScroll = this.getMaxScroll();
      const delta = (e.deltaY || 0) * this.wheelMultiplier;
      this.targetScroll = clamp(this.targetScroll + delta, 0, this.maxScroll);
      this.isScrolling = true;
    }

    _onTouchStart(e) {
      this.touchStartY = e.touches[0].clientY;
      this.touchLastY = this.touchStartY;
    }

    _onTouchMove(e) {
      if (!this.smoothTouch || this.isStopped) return;
      const touchY = e.touches[0].clientY;
      const delta = (this.touchLastY - touchY) * this.touchMultiplier;
      this.touchLastY = touchY;

      this.maxScroll = this.getMaxScroll();
      this.targetScroll = clamp(this.targetScroll + delta, 0, this.maxScroll);
      this.isScrolling = true;
    }

    _onResize() {
      this.maxScroll = this.getMaxScroll();
      this.targetScroll = clamp(this.targetScroll, 0, this.maxScroll);
    }

    _onKey(e) {
      if (['input', 'textarea', 'select'].includes(e.target.tagName.toLowerCase())) return;
      let delta = 0;
      if (e.key === 'ArrowDown') delta = 80;
      else if (e.key === 'ArrowUp') delta = -80;
      else if (e.key === 'PageDown' || (e.key === ' ' && !e.shiftKey)) delta = window.innerHeight * 0.8;
      else if (e.key === 'PageUp' || (e.key === ' ' && e.shiftKey)) delta = -window.innerHeight * 0.8;
      else if (e.key === 'Home') { this.scrollTo(0); return; }
      else if (e.key === 'End') { this.scrollTo(this.maxScroll); return; }

      if (delta !== 0) {
        e.preventDefault();
        this.maxScroll = this.getMaxScroll();
        this.targetScroll = clamp(this.targetScroll + delta, 0, this.maxScroll);
        this.isScrolling = true;
      }
    }

    _startRaf() {
      const loop = (now) => {
        const dt = Math.min((now - this.time) / 1000, 0.1);
        this.time = now;

        if (!this.isStopped) {
          // Lerp toward target scroll
          const diff = this.targetScroll - this.currentScroll;
          if (Math.abs(diff) > 0.5) {
            this.currentScroll = damp(this.currentScroll, this.targetScroll, 12, dt);
            window.scrollTo(0, this.currentScroll);
            if (this.onScroll) {
              this.onScroll({
                scroll: this.currentScroll,
                limit: this.maxScroll,
                velocity: diff * dt
              });
            }
          } else if (this.isScrolling) {
            this.currentScroll = this.targetScroll;
            window.scrollTo(0, this.currentScroll);
            this.isScrolling = false;
          }
        }

        this.rafId = requestAnimationFrame(loop);
      };

      this.rafId = requestAnimationFrame(loop);
    }

    scrollTo(target, options = {}) {
      let targetPos = 0;
      if (typeof target === 'number') {
        targetPos = target;
      } else if (target instanceof HTMLElement) {
        const rect = target.getBoundingClientRect();
        targetPos = (window.scrollY || window.pageYOffset) + rect.top + (options.offset || 0);
      }
      this.maxScroll = this.getMaxScroll();
      this.targetScroll = clamp(targetPos, 0, this.maxScroll);
      this.isScrolling = true;
    }

    stop() {
      this.isStopped = true;
    }

    start() {
      this.isStopped = false;
      this.targetScroll = window.scrollY || window.pageYOffset;
      this.currentScroll = this.targetScroll;
    }

    destroy() {
      this.stop();
      if (this.rafId) cancelAnimationFrame(this.rafId);
      window.removeEventListener('wheel', this._onWheel);
      window.removeEventListener('resize', this._onResize);
      window.removeEventListener('keydown', this._onKey);
      document.documentElement.classList.remove('lenis', 'lenis-smooth');
    }
  }

  // Export to global
  global.Lenis = Lenis;

  // Auto-initialize if not opted out
  function initLenis() {
    if (!window.lenisInstance && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      window.lenisInstance = new Lenis({
        lerp: 0.09,
        duration: 1.1,
        smoothWheel: true,
        smoothTouch: false
      });
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initLenis);
  } else {
    initLenis();
  }

})(typeof window !== 'undefined' ? window : this);
